INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷112·太祖本纪三·广顺二年二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1fbdfd3758d9dbd47716e033cd59ac5314255f5a/content/books/zizhi-tongjian/vol-290/year-0952/part-02/sources/library/jiuwudaishi-112-february-952/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺二年二月，段落 jiu-wudaishi-205deb4a7860-p002670；已核上下文及传主，纸本及异文待核。", "id": "abea5dfa-9015-5e88-b3a6-db10a47db1d5"}, {"title": "旧五代史·卷112·太祖本纪三·广顺二年三月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1fbdfd3758d9dbd47716e033cd59ac5314255f5a/content/books/zizhi-tongjian/vol-290/year-0952/part-02/sources/library/jiuwudaishi-112-march-952/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺二年三月，段落 jiu-wudaishi-205deb4a7860-p002671；已核上下文及传主，纸本及异文待核。", "id": "42a349b1-86f1-5cbb-95eb-74cee418bc5d"}, {"title": "宋史·卷478·世家一·南唐李氏·潘佑附传", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1fbdfd3758d9dbd47716e033cd59ac5314255f5a/content/books/zizhi-tongjian/vol-290/year-0952/part-02/sources/library/songshi-478-pan-you/source.txt", "note": "《宋史》卷478·世家一·南唐李氏·潘佑附传，段落 songshi-9c6e46fee832-p074920；已核上下文及传主，纸本及异文待核。", "id": "f9e99d80-80d5-5dc4-8a73-4c3f3348b2e0"}, {"title": "新五代史·卷53·杂传四十一·慕容彦超传·崔周度阎弘鲁案", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1fbdfd3758d9dbd47716e033cd59ac5314255f5a/content/books/zizhi-tongjian/vol-290/year-0952/part-02/sources/library/xinwudaishi-053-cui-yan-case/source.txt", "note": "《新五代史》卷53·杂传四十一·慕容彦超传·崔周度阎弘鲁案，段落 xin-wudaishi-b08f244b9241-p002081；已核上下文及传主，纸本及异文待核。", "id": "6789532d-b410-58a9-9078-eeafecf7c107"}, {"title": "资治通鉴·卷290·广顺二年·正月起及相邻追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44575c9b45f3f29cba05ba49f0a7a9dc69fba5f3/content/books/zizhi-tongjian/vol-290/year-0952/part-01/sources/library/tongjian-290-952-january-continuation/source.txt", "note": "《资治通鉴》卷290·广顺二年·正月起及相邻追述，段落 zizhi-tongjian-a63549944a71-p003450；已核上下文及传主，纸本及异文待核。", "id": "937a0bab-01af-5f8d-90b3-d3d0aac5e04b"}, {"title": "旧五代史·卷112·太祖本纪三·广顺二年正月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44575c9b45f3f29cba05ba49f0a7a9dc69fba5f3/content/books/zizhi-tongjian/vol-290/year-0952/part-01/sources/library/jiuwudaishi-112-january-952/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺二年正月，段落 jiu-wudaishi-205deb4a7860-p002669；已核上下文及传主，纸本及异文待核。", "id": "1868d873-d8eb-51f9-94b9-48809b88b2cf"}, {"title": "新五代史·卷11·周本纪·广顺二年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/44575c9b45f3f29cba05ba49f0a7a9dc69fba5f3/content/books/zizhi-tongjian/vol-290/year-0952/part-01/sources/library/xinwudaishi-011-second-year-952/source.txt", "note": "《新五代史》卷11·周本纪·广顺二年，段落 xin-wudaishi-b08f244b9241-p000369；已核上下文及传主，纸本及异文待核。", "id": "1e6a3f71-4a0a-5dc5-9317-801e06108ed1"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "崔周度", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 952, "description": "慕容彦超的判官。曾劝慕容彦超不要反叛，后受命搜查阎弘鲁家财，为其说明财物已尽，最终被认为庇护阎弘鲁，在市中被斩。生年未载，死亡年为952年。", "biography": null, "status": "draft", "id": "684c2eaa-df91-5378-9bf2-9af0774f8c6a"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "阎弘鲁", "aliases": ["閻弘魯"], "era": "五代十国", "birth_year": null, "death_year": 952, "description": "阎宝之子，前陕州司马。952年兖州被围时因惧慕容彦超，倾家献财，仍被认为藏有财物，与妻子被拘押、拷打致死。生年未载。", "biography": null, "status": "draft", "id": "01a42515-baaf-5a49-bdc5-d15c6ff0a883"}, {"name": "阎宝", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷262光化三年条所见人物：阎宝。", "biography": null, "status": "draft", "id": "3d9c3ea7-8a06-5aef-a25d-b71110ca2658"}, {"name": "折德扆", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "折从远（后名折从阮）之子，任府州蕃汉马步都指挥使。950年五月己亥获任府州团练使，《宋史》也明确记其父为从阮。生卒年未载。", "biography": null, "status": "draft", "id": "11515d9f-5a90-5398-9366-6f44b89ca847"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "燕敬权", "aliases": ["燕敬權"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。952年正月南唐援慕容彦超的军队在沐阳被后周军击败时被俘。出生、死亡年份未载。", "biography": null, "status": "draft", "id": "e4a3c913-2900-59a5-8cfa-cf946a3458af"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "韩熙载", "aliases": ["韓熙載", "熙载"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：韩熙载，韩叔嗣之子、拟奔吴者。", "biography": null, "status": "draft", "id": "83af8c00-ec9d-5693-9e26-56dc1a5a6a88"}, {"name": "冯延巳", "aliases": ["馮延巳", "冯延己", "馮延己", "冯延已"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，曾任驾部郎中、齐王元帅府常书记。《资治通鉴》本段作冯延己及延已，《新五代史》作冯延巳；据同一南唐政局、陈觉及常梦锡等对应关系校核为同人，展示采用冯延巳，原文异体保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "0b3ed4d7-1a4c-50a5-ad65-aee4b82089ba"}, {"name": "冯延鲁", "aliases": ["馮延魯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯延巳的弟弟，南唐官员，曾任东都判官、礼部员外郎，与兄长同在元帅府。曾请求允许百姓卖子女；李昪去世后又参与起草包含这一规定的遗诏。生卒年尚未核。", "biography": null, "status": "draft", "id": "a589c28e-c0c5-58bf-989f-96457604ccdd"}, {"name": "江文蔚", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：江文蔚，河南巡官、被勒归者。", "biography": null, "status": "draft", "id": "1ea99141-6047-545a-a073-3cae221091a0"}, {"name": "潘佑", "aliases": ["潘佐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐文臣。《资治通鉴》电子底本本段先写潘佐，后简称佑；结合《宋史》韩熙载、徐铉荐其入李璟朝的文学履历，按潘佑记录，原字保留、纸本异文待核。《宋史》记其善论议、入秘书省及崇文馆。生卒年未据本次原文定年。", "biography": null, "status": "draft", "id": "3090a402-3037-5833-bb4c-b07b3056ccc3"}, {"name": "徐铉", "aliases": ["徐鉉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字鼎臣，南唐官员。947年与韩熙载上疏请求处死陈觉、冯延鲁，李璟未采纳。《资治通鉴》此处记会稽，《宋史》记扬州广陵人，籍贯差异保留。生卒年尚未录入。", "biography": null, "status": "draft", "id": "aa3f495d-5349-5093-bee4-984f876430c1"}, {"name": "王克贞", "aliases": ["王克貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "庐陵人。952年南唐初设贡举时，成为三名进士及第者之一。本段未列另外两人姓名，生卒年未载。", "biography": null, "status": "draft", "id": "e2d13ca1-f69b-50e8-85f2-1a7b3bd727fc"}, {"name": "张纬（李金全推官）", "aliases": ["张纬", "張緯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李金全属下推官。史书记载他与胡汉筠互相勾结，以奉承的方式影响李金全，具体起止时间未载。", "biography": null, "status": "draft", "id": "804e88ac-166b-5b44-9fc8-a1db17078f27"}, {"name": "郑仁诲", "aliases": ["鄭仁誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，后周内客省使、恩州团练使。952年三月任枢密副使，新旧五代史同日记载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "f7eb66ac-1c5c-5720-aa2e-9256e75c2b71"}, {"name": "翟光邺", "aliases": ["翟光鄴", "翟光業", "翟光业"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：翟光邺，受遣察安的皇城使。", "biography": null, "status": "draft", "id": "4b6400da-2b69-5857-b364-3106a40c1d45"}, {"name": "徐景运", "aliases": ["徐景運"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐前镇海节度使。952年任中书侍郎、同平章事，与冯延巳、孙晟同为宰相。未与徐景迁、徐景通混同，生卒年未载。", "biography": null, "status": "draft", "id": "69fac4e2-e7c9-5be1-9a5c-7df56a995594"}, {"name": "孙晟", "aliases": ["孫晟", "孙凤", "孫鳳", "孙忌", "孫忌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：孙晟，判官、劝反者。", "biography": null, "status": "draft", "id": "38c30b43-89f4-5133-8970-38f2fb8f157e"}, {"name": "常梦锡", "aliases": ["常夢錫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，万年人。941年四月与陈觉一起被李昪任命为宣徽副使。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "9eaabd48-0b3a-5cc3-a5ec-f9107c987328"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

